#include "gateway/webui_display.h"

#include <string.h>

/* Minified single-file WebUI: zero dependencies, vanilla JS */
static const char *s_html =
    "<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1.0\">\n<title>MimiClaw 控制面板</title>\n<style>\nbody{font-family:system-ui,-apple-system,sans-serif;max-width:480px;margin:0 auto;padding:12px;background:#f5f5f5}\n.card{background:#fff;border-radius:8px;padding:14px;margin-bottom:10px;box-shadow:0 1px 3px rgba(0,0,0,.1)}\nh1{font-size:18px;margin:0 0 10px}\nh2{font-size:15px;margin:0 0 8px;color:#333}\ninput,textarea,select{width:100%;padding:7px;border:1px solid #ddd;border-radius:4px;box-sizing:border-box;margin-bottom:6px;font-size:13px}\ntextarea{resize:vertical;min-height:60px}\nbutton{background:#007aff;color:#fff;border:none;padding:6px 12px;border-radius:4px;cursor:pointer;font-size:13px;margin-right:4px;margin-bottom:4px}\nbutton:hover{background:#0056d6}button:disabled{background:#ccc}\n.status{font-size:12px;color:#666;margin-bottom:10px}\n.status.ok{color:#28a745}.status.err{color:#dc3545}\n.todo-row{display:flex;gap:6px;margin-bottom:4px}\n.todo-row input{flex:1;margin-bottom:0}\n.todo-row button{background:#dc3545;padding:3px 8px;font-size:11px}\n#state{white-space:pre-wrap;font-size:11px;background:#f8f9fa;padding:8px;border-radius:4px;max-height:200px;overflow:auto}\n.tabs{display:flex;gap:4px;margin-bottom:10px;flex-wrap:wrap}\n.tab-btn{background:#e9ecef;color:#333;padding:6px 10px;font-size:12px}\n.tab-btn.active{background:#007aff;color:#fff}\n.tab-content{display:none}\n.tab-content.active{display:block}\n.chat-box{max-height:300px;overflow-y:auto;margin-bottom:8px;background:#f8f9fa;padding:8px;border-radius:4px}\n.chat-msg{margin-bottom:6px;padding:6px 10px;border-radius:12px;max-width:85%;word-break:break-word;font-size:13px}\n.chat-user{background:#007aff;color:#fff;margin-left:auto;text-align:right}\n.chat-ai{background:#e9ecef;color:#333;margin-right:auto}\n.chat-typing{font-size:12px;color:#666;font-style:italic}\n.file-list{max-height:200px;overflow-y:auto;margin-bottom:8px}\n.file-item{padding:4px 6px;cursor:pointer;border-radius:3px;font-size:13px}\n.file-item:hover{background:#e9ecef}\n.file-item.selected{background:#cce5ff}\n.gpio-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(80px,1fr));gap:6px}\n.gpio-item{text-align:center;padding:6px;background:#f8f9fa;border-radius:4px;font-size:12px}\n.gpio-item .pin-num{font-weight:bold;margin-bottom:4px}\n.gpio-item button{padding:3px 8px;font-size:11px;margin:2px}\n.gpio-on{background:#28a745}.gpio-off{background:#dc3545}\n#imgPreview{width:128px;height:296px;border:1px solid #ddd;background:#fff;margin:8px auto;display:none}\n</style>\n</head>\n<body>\n<h1>MimiClaw 控制面板</h1>\n<div class=\"status\" id=\"conn\">连接中...</div>\n<div class=\"tabs\">\n<button class=\"tab-btn active\" onclick=\"showTab('display')\">墨水屏</button>\n<button class=\"tab-btn\" onclick=\"showTab('chat')\">聊天</button>\n<button class=\"tab-btn\" onclick=\"showTab('files')\">文件</button>\n<button class=\"tab-btn\" onclick=\"showTab('image')\">图片</button>\n<button class=\"tab-btn\" onclick=\"showTab('gpio')\">GPIO</button>\n</div>\n\n<div id=\"tab-display\" class=\"tab-content active\">\n<div class=\"card\">\n<div style=\"display:flex;gap:6px;margin-bottom:8px\">\n<button onclick=\"getState()\">获取状态</button>\n<button onclick=\"refresh()\">刷新屏幕</button><button onclick=\"clearScreen()\">清空屏幕</button>\n</div>\n<h2>当前状态</h2><div id=\"state\">等待连接...</div>\n</div>\n<div class=\"card\"><h2>天气</h2>\n<input id=\"city\" placeholder=\"城市\">\n<input id=\"summary\" placeholder=\"天气摘要\">\n<button onclick=\"setWeather()\">更新天气</button>\n</div>\n<div class=\"card\"><h2>待办事项</h2><div id=\"todos\"></div>\n<button onclick=\"addTodo()\">添加待办</button>\n<button onclick=\"setTodos()\">更新待办</button>\n</div>\n<div class=\"card\"><h2>每日金句</h2>\n<textarea id=\"quote\" placeholder=\"金句内容\"></textarea>\n<button onclick=\"setQuote()\">更新金句</button>\n</div>\n</div>\n\n<div id=\"tab-chat\" class=\"tab-content\">\n<div class=\"card\">\n<div class=\"chat-box\" id=\"chatBox\"></div>\n<input id=\"chatInput\" placeholder=\"输入消息...\" onkeydown=\"if(event.key==='Enter')sendChat()\">\n<button onclick=\"sendChat()\">发送</button>\n<button onclick=\"clearChat()\">清空</button>\n</div>\n</div>\n\n<div id=\"tab-files\" class=\"tab-content\">\n<div class=\"card\">\n<button onclick=\"listFiles()\">刷新列表</button>\n<div class=\"file-list\" id=\"fileList\"></div>\n<input id=\"filePath\" placeholder=\"文件路径\" readonly>\n<textarea id=\"fileContent\" placeholder=\"文件内容\"></textarea>\n<button onclick=\"saveFile()\">保存</button>\n<button onclick=\"deleteFile()\">删除</button>\n</div>\n</div>\n\n<div id=\"tab-image\" class=\"tab-content\">\n<div class=\"card\">\n<input type=\"file\" id=\"imgInput\" accept=\"image/*\" onchange=\"previewImg()\">\n<canvas id=\"imgPreview\" width=\"128\" height=\"296\"></canvas>\n<button onclick=\"uploadImg()\">上传到墨水屏</button>\n</div>\n</div>\n\n<div id=\"tab-gpio\" class=\"tab-content\">\n<div class=\"card\">\n<button onclick=\"readAllGpio()\">刷新全部</button>\n<div class=\"gpio-grid\" id=\"gpioGrid\"></div>\n</div>\n</div>\n\n<script>\nlet ws;const $=id=>document.getElementById(id);\nlet chatMsgs=[];let selFilePath='';let gpioStates={};\nfunction connect(){\nws=new WebSocket('ws://'+location.hostname+':18789/');\nws.onopen=()=>{$('conn').textContent='已连接';$('conn').className='status ok';getState();readAllGpio();};\nws.onclose=()=>{$('conn').textContent='已断开，5秒后重连...';$('conn').className='status err';setTimeout(connect,5000);};\nws.onerror=()=>{$('conn').textContent='连接错误';$('conn').className='status err';};\nws.onmessage=e=>{\nconst d=JSON.parse(e.data);\nif(d.type==='display_state'){$('state').textContent=JSON.stringify(d.state,null,2);if(d.state){$('city').value=d.state.weather_city||'';$('summary').value=d.state.weather_summary||'';$('quote').value=d.state.quote||'';renderTodos(d.state.todos||[]);}}\nelse if(d.type==='display_ack'){if(d.status!=='ok')alert(d.action+' 失败: '+(d.message||''));else if(d.action!=='refresh')getState();}\nelse if(d.type==='response'){addChatMsg(d.content,'ai');}\nelse if(d.type==='file_ack'){if(d.status==='ok'&&d.action==='list')renderFiles(d.files||[]);else if(d.status==='ok'&&d.action==='read')$('fileContent').value=d.content||'';else if(d.status!=='ok')alert('文件操作失败: '+(d.message||''));}\nelse if(d.type==='gpio_ack'){if(d.status==='ok'&&d.action==='read_all')renderGpio(d.pins||[]);else if(d.status==='ok'&&d.action==='read')updateGpioPin(d.pin,d.state);else if(d.status==='ok'&&d.action==='write')updateGpioPin(d.pin,d.state);else if(d.status!=='ok')alert('GPIO操作失败: '+(d.message||''));}\n};}\nfunction send(o){if(ws&&ws.readyState===1)ws.send(JSON.stringify(o));}\nfunction showTab(t){document.querySelectorAll('.tab-btn').forEach(b=>b.classList.remove('active'));document.querySelectorAll('.tab-content').forEach(c=>c.classList.remove('active'));event.target.classList.add('active');$('tab-'+t).classList.add('active');}\nfunction getState(){send({type:'display',action:'get_state'});}\nfunction refresh(){send({type:'display',action:'refresh'});}function clearScreen(){send({type:'display',action:'clear'});}\nfunction setWeather(){send({type:'display',action:'set_weather',city:$('city').value,summary:$('summary').value});}\nfunction renderTodos(list){$('todos').innerHTML='';list.forEach(t=>addTodo(t));}\nfunction addTodo(v){const r=document.createElement('div');r.className='todo-row';r.innerHTML='<input value=\"'+(v||'')+'\" placeholder=\"待办内容\"><button onclick=\"this.parentNode.remove()\">删除</button>';$('todos').appendChild(r);}\nfunction setTodos(){const a=[];$('todos').querySelectorAll('input').forEach(i=>{if(i.value.trim())a.push(i.value.trim())});send({type:'display',action:'set_todos',todos:a});}\nfunction setQuote(){send({type:'display',action:'set_quote',quote:$('quote').value});}\n\nfunction sendChat(){const t=$('chatInput').value.trim();if(!t)return;addChatMsg(t,'user');send({type:'message',content:t});$('chatInput').value='';}\nfunction addChatMsg(text,who){const box=$('chatBox');const div=document.createElement('div');div.className='chat-msg chat-'+who;div.textContent=text;box.appendChild(div);box.scrollTop=box.scrollHeight;chatMsgs.push({who,text});if(chatMsgs.length>100){box.removeChild(box.firstChild);chatMsgs.shift();}}\nfunction clearChat(){$('chatBox').innerHTML='';chatMsgs=[];}\n\nfunction listFiles(){send({type:'file',action:'list',path:'/spiffs'});}\nfunction renderFiles(files){const list=$('fileList');list.innerHTML='';files.forEach(f=>{const div=document.createElement('div');div.className='file-item';div.textContent=f;div.onclick=()=>{document.querySelectorAll('.file-item').forEach(i=>i.classList.remove('selected'));div.classList.add('selected');$('filePath').value=f;send({type:'file',action:'read',path:f});};list.appendChild(div);});}\nfunction saveFile(){const p=$('filePath').value;if(!p)return;send({type:'file',action:'write',path:p,content:$('fileContent').value});}\nfunction deleteFile(){const p=$('filePath').value;if(!p)return;if(!confirm('确定删除 '+p+' ?'))return;send({type:'file',action:'delete',path:p});}\n\nfunction previewImg(){const input=$('imgInput');const file=input.files[0];if(!file)return;const reader=new FileReader();reader.onload=e=>{const img=new Image();img.onload=()=>{const canvas=$('imgPreview');const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,128,296);const scale=Math.min(128/img.width,296/img.height);const w=img.width*scale;const h=img.height*scale;const x=(128-w)/2;const y=(296-h)/2;ctx.drawImage(img,x,y,w,h);canvas.style.display='block';};img.src=e.target.result;};reader.readAsDataURL(file);}\nfunction uploadImg(){const canvas=$('imgPreview');if(canvas.style.display==='none'){alert('请先选择图片');return;}const ctx=canvas.getContext('2d');const imgData=ctx.getImageData(0,0,128,296);const fb=packFrame(imgData.data);const b64=btoa(String.fromCharCode(...fb));send({type:'display',action:'show_image',image_b64:b64});}\nfunction packFrame(rgba){const w=128,h=296;const fb=new Uint8Array(w*h/4);const palette=[[0,0,0],[255,255,255],[255,255,0],[255,0,0]];const idx=new Int16Array(w*h);const errR=new Float32Array(w*h);const errG=new Float32Array(w*h);const errB=new Float32Array(w*h);for(let y=0;y<h;y++){for(let x=0;x<w;x++){const i=(y*w+x)*4;let r=rgba[i]+errR[y*w+x];let g=rgba[i+1]+errG[y*w+x];let b=rgba[i+2]+errB[y*w+x];let best=0,bestD=1e9;for(let c=0;c<4;c++){const dr=r-palette[c][0];const dg=g-palette[c][1];const db=b-palette[c][2];const d=dr*dr+dg*dg+db*db;if(d<bestD){bestD=d;best=c;}}idx[y*w+x]=best;const er=r-palette[best][0];const eg=g-palette[best][1];const eb=b-palette[best][2];if(x+1<w){errR[y*w+x+1]+=er*7/16;errG[y*w+x+1]+=eg*7/16;errB[y*w+x+1]+=eb*7/16;}if(y+1<h){if(x>0){errR[(y+1)*w+x-1]+=er*3/16;errG[(y+1)*w+x-1]+=eg*3/16;errB[(y+1)*w+x-1]+=eb*3/16;}errR[(y+1)*w+x]+=er*5/16;errG[(y+1)*w+x]+=eg*5/16;errB[(y+1)*w+x]+=eb*5/16;if(x+1<w){errR[(y+1)*w+x+1]+=er*1/16;errG[(y+1)*w+x+1]+=eg*1/16;errB[(y+1)*w+x+1]+=eb*1/16;}}}}for(let y=0;y<h;y++){for(let x=0;x<w;x+=4){let b=0;for(let k=0;k<4;k++){b|=(idx[y*w+x+k]&3)<<(6-k*2);}fb[(y*w+x)/4]=b;}}return fb;}\n\nfunction readAllGpio(){send({type:'gpio',action:'read_all'});}\nfunction renderGpio(pins){const grid=$('gpioGrid');grid.innerHTML='';pins.forEach(p=>{gpioStates[p.pin]=p.state;const div=document.createElement('div');div.className='gpio-item';div.id='gpio-'+p.pin;div.innerHTML='<div class=\"pin-num\">GPIO '+p.pin+'</div><button class=\"'+(p.state?'gpio-on':'gpio-off')+'\" onclick=\"toggleGpio('+p.pin+')\">'+(p.state?'ON':'OFF')+'</button>';grid.appendChild(div);});}\nfunction updateGpioPin(pin,state){gpioStates[pin]=state;const div=$('gpio-'+pin);if(div){const btn=div.querySelector('button');btn.className=state?'gpio-on':'gpio-off';btn.textContent=state?'ON':'OFF';}}\nfunction toggleGpio(pin){const newState=gpioStates[pin]?0:1;send({type:'gpio',action:'write',pin:pin,state:newState});}\n\nconnect();\n</script>\n</body>\n</html>\n";


esp_err_t webui_handler(httpd_req_t *req)
{
    httpd_resp_set_type(req, "text/html; charset=utf-8");
    httpd_resp_set_hdr(req, "Cache-Control", "no-cache");
    return httpd_resp_send(req, s_html, strlen(s_html));
}
